/*~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
~~ _underwriting.scss
~~
~~ This file contains the styles for the underwriting pages
~~
~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~*/
.dct_uw {
	#main {
		position: relative;
	}

	&.UWA_AccountSearch_body,
	&.Clearance_body {

		#main {
			padding: 0;
			border: $main-body-border-width solid $border-color;
			border-radius:$main-body-border-radius;
			display: flex;
			flex-flow: row wrap;
			justify-content: space-between;
			
			#pageTop {
				background: get-color('white');
				border-radius: 0;
				border-bottom: 1px solid $border-color;
				
				margin: 0;
				 
				 > #pageTitle {
					font-family: $section-title-font-family;
					font-weight: $section-title-font-weight;
					color: $section-title-color;
					font-size: $section-title-font-size;
					padding: $section-title-padding;
				 }
			}
			
			#leftPanelArea {
				display: block;
				background: $nav-left-bgcolor;
				border-right: 1px solid $border-color;
				margin-bottom: 0;
				padding-left: $vertical-gutter-tight;
				padding-right: 0;
				
				#pageNav {
					border-right: none;
					border-bottom: none;
				}
				
				#policyActiveSection {
					margin-top: $horizontal-gutter;
					margin-right: $vertical-gutter;
					margin-bottom: $vertical-gutter-tight;
					padding: 0;
					
					background: get-color('white');
					border: 1px solid $border-color;
					box-shadow: $card-style1-border-shadow;
					
					#activeAccount {
						border-left: 3px solid get-color('action');
						min-height: 1rem;
						padding: $horizontal-gutter-tight $vertical-gutter;
						
						> *:empty {
							display: none;
						}
					}
				}
			}
			
			#fields {
				padding: $main-body-padding;
				margin-bottom: 0;
				
				.acrossLayout > .formTable {
					width: auto;
					> tbody > tr {
						> td {
							padding-right: $horizontal-gutter;
						}
					}
				}
			}
			
			.contentFieldGroup {
				top: .25rem;
			}
			
			> .x_footer {
				display: none;
			}
		}
	}

	&.ApplicantContact_body {
		.downLayout {
			> .formTable {
				width: auto;
			}
		}
	}
	
	&.GeneralInformation_body {
		.acrossFieldGroup {
			width: 100%;
		}
	}
	
	.contentFieldGroup {
		position: absolute;
		width: 19rem !important;
		right: 0;
		top: .5rem;
	}

	i[class*=".png"] {
		display: inline-block;
		font-style: normal;
		font-variant: normal;
		text-rendering: auto;
		
		&::before {
			font-family: 'Font Awesome 5 Free';
			font-weight: 900;
		}
		
	}

	i[class*="house.png"]::before {
		content: "\f015";
	}

	i[class*="email_open.png"]::before {
		content: "\f2b6";
	}
	
	i[class*="note.png"]::before {
		content: "\f249";
	}
	
	i[class*="clipboard.png"]::before {
		content: "\f0ae";
	}
	
	i[class*="magnifier.png"]::before {
		content: "\f002";
	}

	#Create i[class*="magnifier.png"]::before {
		content: "\f055";
	}
}