.dct_bil {
	#itemListDetail, #billingPaymentDetail {
			flex-flow: row nowrap;
			justify-content: stretch;
			>* {
				flex: 1 1 auto;
			}
			.displayTblTitle, .displayTblFooter {
				font-size: get-font-size('normal');
			}
			.displayTblTitle {
				display:block;
			}
			.displayTbl tbody {
				tr:first-child>td {
					font-size: get-font-size('large');
					padding: $vertical-gutter-tighter $horizontal-gutter-tight;
				}
			.displayTblHdr td {
					font-size: $grid-header-label-font-size;
					padding: $vertical-gutter-tighter $horizontal-gutter-tight;
					border-bottom: $grid-border;
				}
			.displayTblRow td {
					font-size: get-font-size('normal');
					padding: $vertical-gutter-tighter $horizontal-gutter-tight;
				}
			}
			#tblItemListDetail .displayTbl tbody {
				.displayTableRow td, .displayTblRow td {
					padding: $vertical-gutter-very-tight $horizontal-gutter-tight;
				}
			}
	}
	#policyTermExtendedData, #policyHeaderDetail, .policySections, .paymentSections {
		display: flex;
		flex-flow: row nowrap;
		justify-content: stretch;
		>* {
			flex: 1 1 auto;
		}
		.displayTable tbody, .acctSummaryInvoiceTable tbody {
			tr:first-child>td {
				font-size: get-font-size('large');
				padding: $vertical-gutter-tighter $horizontal-gutter-tight;
			}
			.displayTableHdr td, .acctSummaryInvoiceTableHdr td {
				font-size: $grid-header-label-font-size;
				padding: $vertical-gutter-tighter $horizontal-gutter-tight;
				border-bottom: $grid-border;
			}
			.displayTableRow td, .acctSummaryInvoiceTableRow td {
				font-size: get-font-size('normal');
				padding: $vertical-gutter-tighter $horizontal-gutter-tight;
			}
		}
		#nextInstallment .displayTable tbody, #billingOutstandingInvoice .acctSummaryInvoiceTable tbody {
			.acctSummaryInvoiceTableRow td {
				padding: $vertical-gutter-less-tight $horizontal-gutter-tight;
			}
			.displayTableRow td {
				padding: $vertical-gutter-very-tight $horizontal-gutter-tight;
			}
		}
	}
	#accountInformationArea {
		.x-panel-header {
			padding: $vertical-gutter-tighter $horizontal-gutter-tight;
		}
		.formTable td {
			padding: $vertical-gutter-tighter 0;
		}
		.x-panel-body .x-panel-body {
			padding: $vertical-gutter-tighter $horizontal-gutter-tight;
			.g-hyperlink .g-btn-text {
				padding-left: 0;
			}
		}
	}
}

